function richTextToHTML(text, ranges) {
  const cuts = [...new Set([0, text.length, ...ranges.flatMap(r => [r.start, r.end])])].sort((a, b) => a - b);
  const esc = s => s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  let html = '';
  for (let i = 0; i < cuts.length - 1; i++) {
    const [s, e] = [cuts[i], cuts[i + 1]];
    const tags = ranges.filter(r => r.start <= s && r.end >= e).map(r => r.tag);
    html += tags.map(t => `<${t}>`).join('') + esc(text.slice(s, e)) + tags.reverse().map(t => `</${t}>`).join('');
  }
  return html;
}

