function useUndo(initial) {
  const [s, setS] = useState({ past: [], present: initial, future: [] });
  const set = v => setS(({ past, present }) => ({ past: [...past, present], present: v, future: [] }));
  const undo = () => setS(({ past, present, future }) => past.length ? { past: past.slice(0, -1), present: past.at(-1), future: [present, ...future] } : { past, present, future });
  const redo = () => setS(({ past, present, future }) => future.length ? { past: [...past, present], present: future[0], future: future.slice(1) } : { past, present, future });
  return { value: s.present, set, undo, redo, canUndo: s.past.length > 0, canRedo: s.future.length > 0 };
}
