export function useForm(initial, rules) {
  const [values, setValues] = useState(initial), [touched, setTouched] = useState({});
  const errors = Object.fromEntries(Object.entries(rules).map(([k, fn]) => [k, fn(values[k], values)]).filter(([, e]) => e));
