function maxLoad(events, W) { // events: [{t, load}]
  events.sort((a, b) => a.t - b.t);
  let sum = 0, best = 0, i = 0;
  for (let j = 0; j < events.length; j++) {
    sum += events[j].load;
    while (events[j].t - events[i].t >= W) sum -= events[i++].load;
    best = Math.max(best, sum);
  }
  return best;
}

