function minWindow(s, t) {
  const need = new Map(); for (const c of t) need.set(c, (need.get(c) || 0) + 1);
  let missing = t.length, l = 0, best = [0, Infinity];
  for (let r = 0; r < s.length; r++) {
    if (need.has(s[r])) { if (need.get(s[r]) > 0) missing--; need.set(s[r], need.get(s[r]) - 1); }
    while (missing === 0) {
      if (r - l < best[1] - best[0]) best = [l, r];
      if (need.has(s[l])) { need.set(s[l], need.get(s[l]) + 1); if (need.get(s[l]) > 0) missing++; }
      l++;
    }
  }
  return best[1] === Infinity ? "" : s.slice(best[0], best[1] + 1);
}
