function paginate(total, page, size = 10, span = 1) {
  const pages = Math.max(1, Math.ceil(total / size));
  page = Math.min(Math.max(1, page), pages);
  const nums = [];
  for (let p = 1; p <= pages; p++)
    if (p === 1 || p === pages || Math.abs(p - page) <= span) nums.push(p);
    else if (nums.at(-1) !== "…") nums.push("…");
  return { page, pages, start: (page - 1) * size, end: Math.min(page * size, total), nums };
}

