    for (let j = 0; j <= b.length; j++) {
      if (i && dp[i - 1][j] && a[i - 1] === s[i + j - 1]) dp[i][j] = true;
      if (j && dp[i][j - 1] && b[j - 1] === s[i + j - 1]) dp[i][j] = true;
