  const [items, setItems] = useState([]); const history = useRef([]);
  const apply = async (next, request) => {
    history.current.push(items); setItems(next);
    try { await request(); } catch { setItems(history.current.pop()); toast("Couldn't update cart"); }
  };
  const remove = id => apply(items.filter(i => i.id !== id), () => api.remove(id));
  const undo = () => { const prev = history.current.pop(); if (prev) { setItems(prev); api.replace(prev); } };
  return { items, remove, undo };
}

