function ContactForm() {
  const empty = { name: "", email: "", message: "", subscribe: false };
  const [f, setF] = useState(empty), [status, setStatus] = useState("idle");
  const change = e => setF({ ...f, [e.target.name]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  async function submit(e) {
    e.preventDefault(); setStatus("sending");
    try {
      const r = await fetch("/api/contact", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(f) });
      if (!r.ok) throw new Error();
      setF(empty); setStatus("sent");
    } catch { setStatus("error"); }
  }
  return (
    <form onSubmit={submit}>
      <input name="name" required value={f.name} onChange={change} />
      <input name="email" type="email" required value={f.email} onChange={change} />
      <textarea name="message" required value={f.message} onChange={change} />
      <label><input name="subscribe" type="checkbox" checked={f.subscribe} onChange={change} /> Subscribe</label>
      <button disabled={status === "sending"}>Send</button>
      {status === "sent" && <p role="status">Thanks! Message sent.</p>}
      {status === "error" && <p role="alert">Something went wrong. Try again.</p>}
    </form>
  );
}

