  const [tasks, setTasks] = useState([]), [draft, setDraft] = useState({ title: "", description: "", priority: "medium" });
  const add = e => { e.preventDefault(); if (!draft.title) return; setTasks(t => [...t, { ...draft, id: crypto.randomUUID(), done: false }]); setDraft({ ...draft, title: "", description: "" }); };
  const update = (id, patch) => setTasks(t => t.map(x => x.id === id ? { ...x, ...patch } : x));
  return (<>
    <form onSubmit={add}>
      <input value={draft.title} onChange={e => setDraft({ ...draft, title: e.target.value })} placeholder="Title" />
      <input value={draft.description} onChange={e => setDraft({ ...draft, description: e.target.value })} placeholder="Description" />
      <select value={draft.priority} onChange={e => setDraft({ ...draft, priority: e.target.value })}><option>high</option><option>medium</option><option>low</option></select>
      <button>Add</button>
    </form>
    <ul>{tasks.map(t => <li key={t.id}>
      <input type="checkbox" checked={t.done} onChange={() => update(t.id, { done: !t.done })} />
      <span style={{ textDecoration: t.done ? "line-through" : "none" }}
        onDoubleClick={() => { const title = prompt("Edit title", t.title); if (title) update(t.id, { title }); }}>
        [{t.priority}] {t.title} — {t.description}</span>
      <button onClick={() => setTasks(x => x.filter(y => y.id !== t.id))}>Delete</button>
    </li>)}</ul>
  </>);
}

