const rules = {
  name: v => !v ? "Name is required" : !/^[A-Za-z ]+$/.test(v) ? "Letters only" : "",
  email: v => !v ? "Email is required" : !/^\S+@\S+\.\S+$/.test(v) ? "Enter a valid email" : "",
