function Register() {
  const [v, setV] = useState({ name: "", email: "", password: "" }), [show, setShow] = useState(false);
  const errors = Object.fromEntries(Object.keys(rules).map(k => [k, rules[k](v[k])]));
  const submit = e => { e.preventDefault(); setShow(true); if (Object.values(errors).every(x => !x)) alert("Registered"); };
  return (<form onSubmit={submit} noValidate>
    {["name", "email", "password"].map(k => <div key={k}>
      <input name={k} type={k === "password" ? "password" : "text"} value={v[k]} aria-invalid={show && !!errors[k]}
        onChange={e => setV({ ...v, [k]: e.target.value })} />
      {show && errors[k] && <small role="alert">{errors[k]}</small>}
    </div>)}
    <button>Register</button>
  </form>);
}

