let cache = null;
function Users() {
  const [state, setState] = useState(() => cache ? { data: cache, loading: false, error: null } : { data: null, loading: true, error: null });
  const load = useCallback(() => {
    if (cache) return;
    setState({ data: null, loading: true, error: null });
    fetch("https://jsonplaceholder.typicode.com/users")
      .then(r => { if (!r.ok) throw new Error(r.status); return r.json(); })
      .then(d => { cache = d; setState({ data: d, loading: false, error: null }); })
      .catch(e => setState({ data: null, loading: false, error: e }));
  }, []);
  useEffect(load, [load]);
  if (state.loading) return <p>Loading…</p>;
  if (state.error) return <p>Failed. <button onClick={load}>Retry</button></p>;
  return <UserList users={state.data} />;
}
const UserList = memo(({ users }) => <ul>{users.map(u => <li key={u.id}>{u.name}</li>)}</ul>);

