async function loadDashboard(userId) {
  const [profile, notifications, recommendations] = await Promise.allSettled([
    fetchJSON(`/api/users/${userId}`),
    fetchJSON(`/api/users/${userId}/notifications`),
    fetchJSON(`/api/users/${userId}/recommendations`),
  ]);
  const pick = r => (r.status === "fulfilled" ? { data: r.value, error: null } : { data: null, error: r.reason });
  return { profile: pick(profile), notifications: pick(notifications), recommendations: pick(recommendations) };
}
async function fetchJSON(url) {
  const res = await fetch(url, { signal: AbortSignal.timeout(8000) });
  if (!res.ok) throw new Error(`${url} failed: ${res.status}`);
  return res.json();
}

